"""Build a course-informed, self-contained 2024 gender-gap visual audit."""
from pathlib import Path
import csv, json, math, re

root = Path(__file__).resolve().parents[2]
source = root / '交付文件/任务二_百年全景/02_数据表/C_2024代表团女性结构.csv'
target = root / '交付文件/任务二_百年全景/09_课程方法可视分析'
target.mkdir(parents=True, exist_ok=True)
names = dict(zip('USA FRA CHN GBR AUS NED GER ESP ITA JPN BRA KOR CAN NZL DEN HUN SRB POL NOR IND ROU RSA CRO MAR ARG SWE UKR'.split(),
                 '美国 法国 中国 英国 澳大利亚 荷兰 德国 西班牙 意大利 日本 巴西 韩国 加拿大 新西兰 丹麦 匈牙利 塞尔维亚 波兰 挪威 印度 罗马尼亚 南非 克罗地亚 摩洛哥 阿根廷 瑞典 乌克兰'.split()))
dashboard_source = (root / '交付文件/任务二_百年全景/05_交互总览/index.html').read_text(encoding='utf-8')
match = re.search(r'nocZh=(\{.*?\});const displayNoc', dashboard_source)
if match:
    names.update(json.loads(match.group(1)))
def wilson(k,n):
    if not n: return [None,None]
    p=k/n; z=1.96; d=1+z*z/n
    c=(p+z*z/(2*n))/d; h=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d
    return [100*(c-h),100*(c+h)]
rows=[]
for r in csv.DictReader(source.open(encoding='utf-8-sig',newline='')):
    if not r['medal_records'] or not r['female_medal_records']: continue
    n=float(r['medal_records']); k=float(r['female_medal_records']); p=float(r['female_participation_share'])*100
    if n<=0 or k<0 or k>n: continue
    low,high=wilson(k,n)
    rows.append(dict(noc=r['NOC'], name=names.get(r['NOC'],r['NOC']), participants=int(float(r['records'])), medals=int(n), female_medals=int(k), participation=round(p,2), award=round(100*k/n,2), gap=round(100*k/n-p,2), low=round(low-p,2), high=round(high-p,2)))
rows.sort(key=lambda x:-x['medals'])
(target/'2024代表团性别结构_区间数据.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>参与之后｜2024代表团性别结构</title>
<style>:root{--paper:#f1eee7;--ink:#173039;--muted:#627278;--line:#c9d1cc;--blue:#286f86;--orange:#b46e42;--panel:#fbfaf6}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 'Microsoft YaHei',system-ui,sans-serif}a{color:inherit}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:18px clamp(22px,5vw,80px);border-bottom:1px solid var(--line)}.top a{text-decoration:none;font-weight:700}.top small{color:var(--muted)}.hero{min-height:430px;display:grid;grid-template-columns:1fr minmax(280px,500px);align-items:end;gap:6vw;padding:70px clamp(22px,5vw,80px) 65px;background:#142d35;color:#f6f2e8;overflow:hidden;position:relative}.hero:after{content:'';position:absolute;width:min(51vw,690px);aspect-ratio:1;border:1px solid #ffffff34;border-radius:50%;right:-9vw;top:-45%;box-shadow:0 0 0 95px #ffffff09,0 0 0 190px #ffffff06;pointer-events:none}.hero>*{position:relative;z-index:1}.eyebrow{color:#e5bb87;font-size:12px;letter-spacing:.17em}.hero h1{font:500 clamp(60px,8vw,130px)/1.05 'STSong','SimSun',serif;letter-spacing:-.075em;margin:15px 0}.hero p{font-size:18px;max-width:620px;color:#dbe5e2}.hero .question{font:500 clamp(25px,3vw,42px)/1.38 'STSong','SimSun',serif;border-left:2px solid #e5bb87;padding-left:25px}.wrap{max-width:1480px;margin:auto;padding:70px clamp(22px,5vw,80px) 110px}.intro{display:flex;justify-content:space-between;align-items:end;gap:45px;padding-bottom:28px;border-bottom:1px solid var(--line)}h2{font:500 clamp(31px,3vw,48px)/1.2 'STSong','SimSun',serif;margin:10px 0}.intro p{max-width:610px;color:var(--muted)}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:16px;padding:27px 0 22px}.controls label{display:grid;gap:6px;color:var(--muted);font-size:12px;font-weight:700}.controls select{padding:10px 14px;border:1px solid var(--line);border-radius:9px;background:var(--panel);color:var(--ink);font:inherit;min-width:180px}.legend{margin-left:auto;display:flex;gap:20px;align-items:center;font-size:12px;color:var(--muted)}.legend i{width:16px;height:9px;display:inline-block;margin-right:5px}.legend .pos{background:var(--blue)}.legend .neg{background:var(--orange)}.visual{display:grid;grid-template-columns:minmax(0,1fr) minmax(230px,300px);gap:30px}.chart{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:28px 22px 25px}.axis{display:grid;grid-template-columns:140px 1fr 80px;gap:12px;align-items:end;margin-bottom:13px;font-size:12px;color:var(--muted)}.axis .ticks{display:flex;justify-content:space-between}.row{display:grid;grid-template-columns:140px 1fr 80px;gap:12px;align-items:center;min-height:39px;border-top:1px solid #dfe4de;cursor:pointer;transition:background .2s}.row:hover,.row.active{background:#e5efec}.name{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-left:4px}.track{position:relative;height:20px}.zero{position:absolute;left:50%;height:26px;top:-3px;border-left:1px solid #60777c}.bar{position:absolute;top:6px;height:8px;border-radius:2px;background:var(--blue);transform-origin:center}.bar.neg{background:var(--orange)}.interval{position:absolute;top:9px;border-top:2px solid #374e55;height:0}.interval:before,.interval:after{content:'';position:absolute;top:-5px;height:8px;border-left:1px solid #374e55}.interval:before{left:0}.interval:after{right:0}.point{position:absolute;top:4px;width:12px;height:12px;border:2px solid var(--panel);border-radius:50%;background:var(--blue);transform:translateX(-50%)}.point.neg{background:var(--orange)}.value{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}.detail{background:#dfebe7;border-radius:14px;padding:30px;align-self:start;position:sticky;top:20px}.detail .tag{font-size:11px;color:#486a70;letter-spacing:.12em}.detail h3{font:500 38px/1.2 'STSong','SimSun',serif;margin:12px 0 22px}.detail .big{font:600 54px/1 Georgia,serif;color:var(--blue)}.detail .big.neg{color:var(--orange)}.detail p{margin:18px 0;color:#3d5559}.detail dl{display:grid;grid-template-columns:1fr auto;gap:9px;margin:25px 0 0;padding-top:20px;border-top:1px solid #aebfbb}.detail dt{color:#587075}.detail dd{margin:0;font-weight:700}.notes{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:45px}.note{border-top:2px solid var(--ink);padding-top:15px}.note b{font-size:18px}.note p{color:var(--muted)}footer{border-top:1px solid var(--line);padding:30px clamp(22px,5vw,80px);font-size:12px;color:var(--muted)}:focus-visible{outline:3px solid #d4965c;outline-offset:3px}@media(max-width:900px){.hero,.visual{grid-template-columns:1fr}.detail{position:static}.notes{grid-template-columns:1fr}.intro{display:block}}@media(max-width:600px){.axis,.row{grid-template-columns:85px 1fr 56px;gap:6px}.chart{padding:18px 8px}.legend{margin-left:0}.row{font-size:12px}.hero{min-height:350px;padding-top:45px}}
</style></head><body><nav class="top"><a href="../index.html">← 百年全景</a><small>课程方法实验 · 2024</small></nav><header class="hero"><div><div class="eyebrow">数据的分母，决定故事的方向</div><h1>参与之后</h1><p>女性参与比例接近一半时，领奖台上的比例也会同步接近吗？把每个代表团放在同一条零线两侧，让差距、样本量和区间一起说话。</p></div><div class="question">一眼可见的差距，<br>未必是稳得住的结论。</div></header><main class="wrap"><section class="intro"><div><small class="eyebrow" style="color:#9a684c">01 / 同一个问题，两种比例</small><h2>谁参与，谁留下成绩？</h2></div><p>横轴为“女性获奖运动员行占比－女性参赛记录占比”，单位百分点。蓝色为高于参与份额，橙色为低于参与份额；细线是获奖份额的 Wilson 95% 区间平移到差距轴。位置与长度承载数值，颜色只帮助辨认方向。</p></section><div class="controls"><label>最低获奖行数<select id="threshold"><option value="10">10 行 · 探索</option><option value="20">20 行 · 观察</option><option value="30" selected>30 行 · 主视图</option><option value="50">50 行 · 大样本</option></select></label><label>排列方式<select id="sort"><option value="gap">按差距排列</option><option value="medals">按获奖行数排列</option><option value="name">按代表团名称排列</option></select></label><span id="count" aria-live="polite"></span><div class="legend"><span><i class="pos"></i>高于参与份额</span><span><i class="neg"></i>低于参与份额</span></div></div><div class="visual"><div class="chart" id="chart" role="list" aria-label="代表团女性参与与获奖结构差"></div><aside class="detail" id="detail" aria-live="polite"></aside></div><section class="notes"><div class="note"><b>看零线，而非只看排名</b><p>零表示获奖结构与参与结构相同。条越长，差距越大；比较正负两侧时保持完全相同的轴尺度。</p></div><div class="note"><b>区间只说明抽样波动</b><p>Wilson 区间以获奖行作为近似独立观测。团队项目同队多人获奖会产生相关性，因此区间只是保守的阅读提示，不能当成严格推断或因果证据。</p></div><div class="note"><b>指标不是能力或公平度</b><p>参赛记录与获奖运动员行都受项目结构、席位和团队规模影响。要解释机制，还需按运动大类分层，并比较官方小项口径；本页不把结构差直接解释为性别待遇。</p></div></section></main><footer>数据：任务二《C_2024代表团女性结构.csv》；计算：<a href="2024代表团性别结构_区间数据.json">区间数据</a>。2024 巴黎夏奥会；运动员行口径，非官方小项奖牌数。设计依据：课程 PPT 第 2 讲“位置优先、分组靠距离”、第 7 讲“小倍数与交互过滤”。</footer><script>const DATA=__DATA__;const chart=document.querySelector('#chart'),detail=document.querySelector('#detail'),threshold=document.querySelector('#threshold'),sort=document.querySelector('#sort'),count=document.querySelector('#count');let selected='';const clamp=n=>Math.max(-70,Math.min(70,n));const pct=n=>`${n>0?'+':''}${n.toFixed(1)} 个百分点`;const x=n=>50+clamp(n)/140*100;function render(){let a=DATA.filter(d=>d.medals>=+threshold.value);if(sort.value==='gap')a.sort((u,v)=>v.gap-u.gap);else if(sort.value==='medals')a.sort((u,v)=>v.medals-u.medals);else a.sort((u,v)=>u.name.localeCompare(v.name,'zh'));count.textContent=`${a.length} 个代表团`;chart.innerHTML='<div class="axis"><span>代表团</span><span class="ticks"><span>−70</span><span>−35</span><span>0</span><span>+35</span><span>+70</span></span><span style="text-align:right">差距</span></div>'+a.map(d=>{let end=x(d.gap),left=Math.min(50,end),width=Math.abs(end-50),il=x(d.low),ih=x(d.high);return `<div class="row" role="listitem" tabindex="0" data-noc="${d.noc}" aria-label="${d.name}，差距${pct(d.gap)}，${d.medals}条获奖记录"><span class="name">${d.name}</span><span class="track"><i class="zero"></i><i class="bar ${d.gap<0?'neg':''}" style="left:${left}%;width:${width}%"></i><i class="interval" style="left:${il}%;width:${Math.max(0,ih-il)}%"></i><i class="point ${d.gap<0?'neg':''}" style="left:${end}%"></i></span><span class="value">${d.gap>0?'+':''}${d.gap.toFixed(1)}</span></div>`}).join('');chart.querySelectorAll('.row').forEach(el=>{el.addEventListener('click',()=>pick(el.dataset.noc,a));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(el.dataset.noc,a)}})});pick(a.some(d=>d.noc===selected)?selected:a[0]?.noc,a)}function pick(noc,a){const d=a.find(x=>x.noc===noc);if(!d){detail.innerHTML='当前门槛下没有数据。';return}selected=noc;chart.querySelectorAll('.row').forEach(el=>el.classList.toggle('active',el.dataset.noc===noc));detail.innerHTML=`<div class="tag">代表团结构 / ${d.noc}</div><h3>${d.name}</h3><div class="big ${d.gap<0?'neg':''}">${pct(d.gap)}</div><p>获奖份额为 ${d.award.toFixed(1)}%，参与份额为 ${d.participation.toFixed(1)}%。该差距是结构描述，不能单凭它判断原因。</p><dl><dt>女性参赛记录占比</dt><dd>${d.participation.toFixed(1)}%</dd><dt>女性获奖行占比</dt><dd>${d.award.toFixed(1)}%</dd><dt>获奖运动员行数</dt><dd>${d.medals}</dd><dt>Wilson 区间对应差距</dt><dd>${d.low.toFixed(1)} ～ ${d.high.toFixed(1)}</dd></dl>`}threshold.addEventListener('change',render);sort.addEventListener('change',render);render();</script></body></html>'''
html = html.replace('font:600 54px/1 Georgia,serif;color:var(--blue)', 'font:600 36px/1.2 Georgia,serif;color:var(--blue);white-space:nowrap')
html = html.replace('只是保守的阅读提示', '只是粗略的阅读提示')
(target/'index.html').write_text(html.replace('__DATA__',json.dumps(rows,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
