if 'course-lens-entry' not in page:
    page = page.replace('<!-- CONCENTRATION_END -->','<!-- CONCENTRATION_END -->'+link)
    dashboard.write_text(page,encoding='utf-8')
landing = root / 'index.html'
page = landing.read_text(encoding='utf-8')
needle = '<a href="交付文件/任务二_百年全景/05_交互总览/index.html">进入任务二 <span>↗</span></a>'
if needle in page and '09_课程方法可视分析/index.html' not in page:
    page = page.replace(needle,needle+'<a class="course-lens-link" href="交付文件/任务二_百年全景/09_课程方法可视分析/index.html">参与之后 · 可视分析 ↗</a>')
    landing.write_text(page,encoding='utf-8')
print(f'Built {len(rows)} delegation rows: {target / "index.html"}')
